import pandas as pd
from quant.components.base import BaseComponent
from quant.components.bitview_client import fetch_series
from quant.components.normalization import normalize_metric

class TerminalPriceRatioComponent(BaseComponent):
    METRIC_NAME = "terminal_price_ratio"
    DESCRIPTION = "Terminal Price Ratio"
    CATEGORY = "fundamental"

    def fetch_data(self, full_rebuild: bool = False) -> pd.DataFrame:
        # Fetch full history to compute cumulative sum correctly
        df_cdd = fetch_series("coindays_destroyed_sum_24h")
        df_p = fetch_series("price")
        df_sup = fetch_series("supply")

        if df_cdd.empty or df_p.empty or df_sup.empty:
            return pd.DataFrame()

        df = pd.merge(df_cdd, df_p, on="date", suffixes=("_cdd", "_p"))
        df = pd.merge(df, df_sup, on="date")
        df = df.rename(columns={"value": "value_sup"})

        df = df.dropna(subset=["value_cdd", "value_p", "value_sup"])
        df = df.sort_values("date").reset_index(drop=True)

        if df.empty:
            return pd.DataFrame()

        # Compute Transferred Price = cumsum(CDD * price) / (age_in_days * supply)
        df["cdd_price"] = df["value_cdd"] * df["value_p"]
        df["cum_cdd_price"] = df["cdd_price"].cumsum()
        df["age_in_days"] = range(1, len(df) + 1)

        # Guard against division by zero in supply or age
        df["transferred_price"] = df.apply(
            lambda row: row["cum_cdd_price"] / (row["age_in_days"] * row["value_sup"])
            if row["value_sup"] > 0 else 0.0,
            axis=1
        )

        # Terminal Price = Transferred Price * 21
        df["terminal_price"] = df["transferred_price"] * 21.0

        # Raw value = price / terminal_price
        df["raw_value"] = df.apply(
            lambda row: row["value_p"] / row["terminal_price"] if row["terminal_price"] > 0 else 0.0,
            axis=1
        )
        df["btc_price"] = df["value_p"]

        # Filter for delta if not full_rebuild
        if not full_rebuild:
            start_date = self.get_latest_date()
            if start_date:
                df = df[df["date"] > start_date]

        return df

    def normalize(self, df: pd.DataFrame) -> pd.DataFrame:
        df["normalized_value"] = df["raw_value"].apply(
            lambda val: normalize_metric(self.db_path, self.METRIC_NAME, val)
        )
        return df

